@pytest.mark.parametrize("esmiles1,esmiles2,groundtruth", test_samples)
def test_compare_samples(esmiles1, esmiles2, groundtruth):
	comparator = MoleculeComparator(Translator)
	prediction = comparator.compare(esmiles1, esmiles2)
	# assert if prediction == groundtruth
	# 断言返回状态是 ComparisonState
	assert isinstance(prediction.state, ComparisonState) 
	assert prediction.state.value==groundtruth



